#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-11-11

# page-serve serve.sh must run every python3 call in isolated mode (-I).
#
# Without -I, Python puts the cwd first on sys.path. serve.sh runs the static
# server with cwd = the served folder, and its `-c` / `-` calls run in the
# caller's cwd, so a planted http/__init__.py (served folder) or json.py /
# socket.py (caller cwd) runs as the user. Two parts:
#   1. behavioural: run the real serve.sh with stub portless and curl, with
#      the modules planted; no marker may appear and the server must start.
#   2. static: all five python3 calls carry -I (the behavioural run cannot
#      prove each call site was reached).

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
SERVE="$REPO_ROOT/src/skills/page-serve/scripts/serve.sh"

PASS=0
FAIL=0
ok() { echo "  ✓ $1"; PASS=$((PASS + 1)); }
bad() { echo "  ✗ $1"; FAIL=$((FAIL + 1)); }

if [[ ! -f "$SERVE" ]]; then
    echo "FAIL: $SERVE not found" >&2
    exit 1
fi

TMP="$(mktemp -d "${TMPDIR:-/tmp}/ork.pageserve.XXXXXX")"
cleanup() {
    local rc=$? pid="" tries=0
    # The exact file serve.sh writes: ${CLAUDE_PROJECT_DIR}/.claude/state/page-serve/<name>.json.
    # Not a glob: a shell star never matches the dot in ".claude".
    local state="$TMP/proj/.claude/state/page-serve/ork-ps-test.json"
    if [[ -f "$state" ]]; then
        pid="$(sed -n 's/.*"pid": *\([0-9][0-9]*\).*/\1/p' "$state" | head -1)"
        echo "  state file written by serve.sh: $state pid=$pid"
    fi
    # A cleanup that stops nothing is a failure: the server it started is still running.
    if [[ -z "$pid" ]]; then
        echo "FAIL: cleanup found no page-serve state file or pid, so it stopped no server (leak)" >&2
        rc=1
    else
        # silent: post-cleanup (the server this test started may already be gone)
        kill "$pid" 2>/dev/null || true
        # silent: gating-relaxed (kill -0 is a liveness probe; a dead pid is the expected "no")
        while kill -0 "$pid" 2>/dev/null && [[ "$tries" -lt 20 ]]; do
            sleep 0.2
            tries=$((tries + 1))
        done
        # silent: gating-relaxed (kill -0 is a liveness probe; a dead pid is the expected "no")
        if kill -0 "$pid" 2>/dev/null; then
            echo "FAIL: page-serve server pid $pid is still alive after cleanup (leak)" >&2
            rc=1
        fi
    fi
    rm -rf "$TMP"
    exit "$rc"
}
trap cleanup EXIT

mkdir -p "$TMP/bin" "$TMP/root/http" "$TMP/caller" "$TMP/proj"
echo '<p>x</p>' > "$TMP/root/index.html"

# Stubs: the portless 443 service and the proxy URL are not available here.
cat > "$TMP/bin/portless" <<'EOF'
#!/bin/bash
case "$1" in
  service) echo "Proxy on 443: responding" ;;
  alias) exit 0 ;;
esac
EOF
cat > "$TMP/bin/curl" <<'EOF'
#!/bin/bash
printf '200'
EOF
chmod +x "$TMP/bin/portless" "$TMP/bin/curl"
# The caller cwd lives in this test's own mktemp dir, removed by the trap, so a
# killed run leaves nothing in the repo and parallel runs cannot collide.
CALLER="$TMP/caller"

# Plants: each writes its own marker, then exits 0 so a hit is unambiguous.
printf 'open(%s, "w").write("ran")\nraise SystemExit(0)\n' "'$TMP/marker-http'" > "$TMP/root/http/__init__.py"
printf 'open(%s, "w").write("ran")\nraise SystemExit(0)\n' "'$TMP/marker-json'" > "$CALLER/json.py"
printf 'open(%s, "w").write("ran")\nraise SystemExit(0)\n' "'$TMP/marker-socket'" > "$CALLER/socket.py"

echo "Behavioural: planted modules must not run"
# Exported once here, not as a per-command prefix.
export PATH="$TMP/bin:$PATH"
export CLAUDE_PROJECT_DIR="$TMP/proj"
cd "$CALLER"
RC1=0
OUT1="$(bash "$SERVE" "$TMP/root" --name ork-ps-test --no-screenshot 2>&1)" || RC1=$?
# Second run reuses the live server and reads the state file, which is the json -c call.
RC2=0
OUT2="$(bash "$SERVE" "$TMP/root" --name ork-ps-test --no-screenshot 2>&1)" || RC2=$?
cd "$SCRIPT_DIR"

for m in http json socket; do
    if [[ -f "$TMP/marker-$m" ]]; then bad "planted $m module ran as the user"; else ok "planted $m module did not run"; fi
done
if [[ "$RC1" -eq 0 && "$OUT1" == *"url=https://ork-ps-test.localhost/"* ]]; then ok "first run served the page (rc 0)"; else bad "first run did not serve (rc $RC1): ${OUT1:0:200}"; fi
if [[ "$RC2" -eq 0 && "$OUT2" == *"url=https://ork-ps-test.localhost/"* ]]; then ok "second run reused the server (rc 0)"; else bad "second run failed (rc $RC2): ${OUT2:0:200}"; fi

echo "Static: every python3 call is isolated"
TOTAL=0
ISO=0
# silent: gating-relaxed (grep -c exits 1 on a zero count; the printed count is the answer)
if TOTAL="$(grep -cE '^[^#]*\bpython3 +(-[a-zA-Z]|-( |$))' "$SERVE")"; then :; fi
# silent: gating-relaxed (grep -c exits 1 on a zero count; the printed count is the answer)
if ISO="$(grep -cE '^[^#]*\bpython3 +-I( |$)' "$SERVE")"; then :; fi
if [[ "$TOTAL" -eq 5 ]]; then ok "serve.sh has 5 python3 calls"; else bad "serve.sh has $TOTAL python3 calls (expected 5; update the test if a call was added)"; fi
if [[ "$ISO" -eq "$TOTAL" ]]; then ok "all $TOTAL carry -I"; else bad "only $ISO of $TOTAL python3 calls carry -I"; fi

echo ""
echo "Results: $PASS passed, $FAIL failed"
[[ "$FAIL" -eq 0 ]]
